package com.corecs.cpu.service;
import com.corecs.cpu.algorithm.*;import com.corecs.cpu.dto.SimulationRequest;import com.corecs.cpu.model.SimulationResult;import org.springframework.stereotype.Service;import java.util.*;
@Service public class SchedulingService { private final Map<String,SchedulingAlgorithm> algorithms=Map.of("FCFS",new FcfsAlgorithm(),"SJF",new SjfAlgorithm(),"SRTF",new SrtfAlgorithm(),"PRIORITY",new PriorityAlgorithm(),"ROUND_ROBIN",new RoundRobinAlgorithm()); public SimulationResult simulate(SimulationRequest r){var a=algorithms.get(r.algorithm().toUpperCase());if(a==null)throw new IllegalArgumentException("Unsupported algorithm. Use FCFS, SJF, SRTF, PRIORITY or ROUND_ROBIN");r.processes().forEach(p->{if(p.arrivalTime()<0||p.burstTime()<=0||p.priority()<0)throw new IllegalArgumentException("Arrival must be >= 0, burst > 0, priority >= 0");});return a.simulate(r.processes(),r.timeQuantum());} }
